package com.masterlearning.platform.modules.certificate.entity;
import com.masterlearning.platform.common.entity.BaseEntity; import com.masterlearning.platform.modules.course.entity.Course; import com.masterlearning.platform.modules.user.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="certificates",uniqueConstraints=@UniqueConstraint(columnNames={"course_id","user_id"})) public class Certificate extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=80) private String certificateNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_id",nullable=false) private Course course; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false) private Instant issuedAt=Instant.now(); protected Certificate(){} public Certificate(String n,Course c,User u){certificateNumber=n;course=c;user=u;} public UUID getId(){return id;} public String getCertificateNumber(){return certificateNumber;} }